head.script:
scwin.strNameSpace = 'xmlns:w2="http://www.inswave.com/websquare" xmlns:ev="http://www.w3.org/2001/xml-events" xmlns:xf="http://www.w3.org/2002/xforms"';

scwin.onpageload = async function () {
    // A : 화면의 첫 editor 2개를 dynamicCreate 로 동시에 생성
    await scwin.createEditors("A", grp_a);
};

// editor 2개를 dynamicCreate 로 동시에(Promise.all) 생성
scwin.createEditors = async function (prefix, parent) {
    let ids = [prefix + "_editor1", prefix + "_editor2"];
    await Promise.all(ids.map(function (id) {
        let str = '<w2:editor ' + scwin.strNameSpace + ' id="' + id + '" style="width:400px; height:160px;"></w2:editor>';
        return $p.dynamicCreate(id, "editor", str, parent);
    }));
    setTimeout(function () {
        let cnt = parent.render.querySelectorAll(".cke").length;
        scwin.setReturnValue("[" + prefix + "] 그려진 editor : " + cnt + " / 2");
    }, 1500);
};

scwin.btn_create_onclick = async function (e) {
    if (grp_b.render.querySelectorAll(".w2editor").length > 0) {
        return;
    }
    await scwin.createEditors("B", grp_b);
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
